    private async Task HandleMoveLeft(int taskId) => await OnMoveLeft.InvokeAsync(taskId);
    private async Task HandleMoveRight(int taskId) => await OnMoveRight.InvokeAsync(taskId);
    private async Task HandleTaskCreated(TaskItem task) => await OnTaskCreated.InvokeAsync(task);
}

