arguments.file_text:
@page "/board"
@using sv_a840e6003dfb4604b6c8f032784ffb7f
@using sv_a840e6003dfb4604b6c8f032784ffb7f.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="board-columns">
        @foreach (var column in columns)
        {
            var index = Array.IndexOf(columns, column);
            <BoardColumn Status="@column"
                         Tasks="GetFilteredTasks(column)"
                         CanMoveLeft="index > 0"
                         CanMoveRight="index < columns.Length - 1"
                         OnMoveLeft="taskId => MoveTask(taskId, columns[index - 1])"
                         OnMoveRight="taskId => MoveTask(taskId, columns[index + 1])"
                         OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private readonly string[] columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> allTasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                var old = allTasks[idx];
                allTasks[idx] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(TaskItem placeholder)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(
                placeholder.Title, placeholder.Assignee, placeholder.Priority, placeholder.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

/* ── Summary Bar ── */
.board-summary-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f0f4f8;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.summary-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.summary-label {
    font-size: 0.8rem;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.summary-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #1e293b;
}

.summary-stat-overdue .summary-value {
    color: #dc2626;
}

/* ── Search Bar ── */
.board-search-bar {
    margin-bottom: 1rem;
}

.search-input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

/* ── Columns Layout ── */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.board-column-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e2e8f0;
}

.board-column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.column-count {
    color: #94a3b8;
    font-weight: 400;
}

.board-column-body {
    padding: 0.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

.board-column-footer {
    padding: 0.5rem;
    border-top: 1px solid #e2e8f0;
}

/* ── Task Card ── */
.task-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-card-assignee {
    margin: 0 0 0.4rem;
    font-size: 0.8rem;
    color: #64748b;
}

.task-card-priority {
    display: inline-block;
    padding: 0.15rem 0.5rem;
