toolArgs.file_text:
/* ── Summary Bar ── */
.board-summary-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f0f4f8;
    border-radius: 8px;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.summary-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.summary-label {
    font-size: 0.8rem;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.summary-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #1e293b;
}

.summary-stat-overdue .summary-value {
    color: #dc2626;
}

/* ── Search Bar ── */
.board-search-bar {
    margin-bottom: 1rem;
}

.search-input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

/* ── Columns Layout ── */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.board-column-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e2e8f0;
}

.board-column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.column-count {
    color: #94a3b8;
    font-weight: 400;
}

.board-column-body {
    padding: 0.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

.board-column-footer {
    padding: 0.5rem;
    border-top: 1px solid #e2e8f0;
}

/* ── Task Card ── */
.task-card {
    background: #fff;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-card-title {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

.task-card-assignee {
    margin: 0 0 0.4rem;
    font-size: 0.8rem;
    color: #64748b;
}

.task-card-priority {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #fee2e2;
    color: #dc2626;
}

.priority-medium {
    background: #fef9c3;
    color: #a16207;
}

.priority-low {
    background: #dcfce7;
    color: #16a34a;
}

.task-card-due {
    font-size: 0.8rem;
    color: #64748b;
}

.task-card-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.4rem;
}

.btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

.btn-move:hover {
    background: #f1f5f9;
}

/* ── Add Task ── */
.btn-add-task {
    width: 100%;
    padding: 0.4rem;
    background: transparent;
    border: 1px dashed #94a3b8;
    border-radius: 6px;
    color: #64748b;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    background: #f1f5f9;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.form-input {
    padding: 0.4rem 0.5rem;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    font-size: 0.85rem;
    width: 100%;
    box-sizing: border-box;
}

.add-task-form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save, .btn-cancel {
    flex: 1;
    padding: 0.35rem;
    border: none;
    border-radius: 4px;
    font-size: 0.85rem;
    cursor: pointer;
}

.btn-save {
    background: #2563eb;
    color: #fff;
}

.btn-save:hover {
    background: #1d4ed8;
}

.btn-cancel {
    background: #e2e8f0;
    color: #334155;
}

.btn-cancel:hover {
    background: #cbd5e1;
}

.form-error {
    color: #dc2626;
    font-size: 0.8rem;
    margin: 0;
}

/* ── Loading / Error ── */
.board-loading {
    text-align: center;
    padding: 2rem;
    color: #64748b;
}

.board-error {
    text-align: center;
    padding: 2rem;
    color: #dc2626;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    border: 1px solid #dc2626;
    background: #fff;
    color: #dc2626;
    border-radius: 4px;
    cursor: pointer;
}

