+
+.add-task-form {
+    display: flex;
+    flex-direction: column;
+    gap: 0.4rem;
+}
+
+.form-input {
+    padding: 0.4rem 0.5rem;
+    border: 1px solid #cbd5e1;
+    border-radius: 4px;
+    font-size: 0.85rem;
+    width: 100%;
+    box-sizing: border-box;
+}
+
+.add-task-form-actions {
+    display: flex;
+    gap: 0.4rem;
+}
+
+.btn-save, .btn-cancel {
+    flex: 1;
+    padding: 0.35rem;
+    border: none;
+    border-radius: 4px;
+    font-size: 0.85rem;
+    cursor: pointer;
+}
+
+.btn-save {
+    background: #2563eb;
+    color: #fff;
+}
+
+.btn-save:hover {
+    background: #1d4ed8;
+}
+
+.btn-cancel {
+    background: #e2e8f0;
+    color: #334155;
+}
+
+.btn-cancel:hover {
+    background: #cbd5e1;
+}
+
+.form-error {
+    color: #dc2626;
+    font-size: 0.8rem;
+    margin: 0;
+}
+
+/* ── Loading / Error ── */
+.board-loading {
+    text-align: center;
+    padding: 2rem;
+    color: #64748b;
+}
+
+.board-error {
+    text-align: center;
+    padding: 2rem;
+    color: #dc2626;
+}
+
+.board-error button {
+    margin-top: 0.5rem;
+    padding: 0.4rem 1rem;
+    border: 1px solid #dc2626;
+    background: #fff;
+    color: #dc2626;
+    border-radius: 4px;
+    cursor: pointer;
+}
+

